import AdmissionInfo from '../components/AdmissionInfo.vue';
import RecruitmentInfo from '../components/RecruitmentInfo.vue';
import OnlineRegistration from '../components/OnlineRegistration.vue';
import ContactUs from '../components/ContactUs.vue';
export default {
  name: 'RecruitmentPage',
  components: {
    AdmissionInfo,
    RecruitmentInfo,
    OnlineRegistration,
    ContactUs
  },
  props: {
    activeTab: {
      type: String,
      default: 'recruitment'
    }
  },
  data() {
    return {
      activeTabData: this.activeTab
    };
  },
  computed: {
    activeMenuItem() {
      const mapping = {
        'admission': '/admission',
        'recruitment': '/recruitment',
        'registration': '/registration',
        'contact': '/contact'
      };
      return mapping[this.activeTabData];
    }
  },
  methods: {
    handleTabClick(tab) {
      this.activeTabData = tab.name;
      // 使用路由导航到对应页面
      this.$router.push(this.activeMenuItem);
    }
  },
  // 监听路由变化，更新activeTabData
  watch: {
    $route(to) {
      const path = to.path;
      const reverseMapping = {
        '/admission': 'admission',
        '/recruitment': 'recruitment',
        '/registration': 'registration',
        '/contact': 'contact'
      };
      if (reverseMapping[path]) {
        this.activeTabData = reverseMapping[path];
      }
    }
  },
  // 组件创建时根据当前路由设置activeTabData
  created() {
    const path = this.$route.path;
    const reverseMapping = {
      '/admission': 'admission',
      '/recruitment': 'recruitment',
      '/registration': 'registration',
      '/contact': 'contact'
    };
    if (reverseMapping[path]) {
      this.activeTabData = reverseMapping[path];
    }
  }
};
